import json
import re
from datetime import date

_DAY_RE = re.compile(r'^(?P<year>\d{4})-(?P<month>\d{2})-(?P<day>\d{2})$')


def _clean_day(value, row_index):
    if not isinstance(value, str):
        raise ValueError(f'row {row_index}: day must be a YYYY-MM-DD string')
    match = _DAY_RE.match(value)
    if not match:
        raise ValueError(f'row {row_index}: day is not in YYYY-MM-DD form')
    try:
        date(int(match['year']), int(match['month']), int(match['day']))
    except ValueError:
        raise ValueError(f'row {row_index}: day is not a valid calendar date') from None
    return value


def summarize_rows(text: str):
    """Parse a JSON array of rows. Each row has a nonempty string tenant, an integer
    amount_cents (negative amounts are allowed; booleans are invalid), and a valid YYYY-
    MM-DD string day. Return row_count, total_cents, first_day, and last_day. Empty
    input gives zero totals and null dates. Ignore extra fields. Raise ValueError on
    malformed JSON or rows."""
    try:
        payload = json.loads(text)
    except ValueError as exc:
        raise ValueError(f'malformed JSON: {exc}') from exc
    if not isinstance(payload, list):
        raise ValueError('malformed rows: input must be a JSON array')
    row_count = 0
    total_cents = 0
    first_day = None
    last_day = None
    for index, row in enumerate(payload):
        if not isinstance(row, dict):
            raise ValueError(f'malformed rows: row {index} must be an object')
        tenant = row.get('tenant')
        if not isinstance(tenant, str) or not tenant:
            raise ValueError(f'malformed rows: row {index} must have a nonempty tenant')
        amount_cents = row.get('amount_cents')
        if type(amount_cents) is not int:
            raise ValueError(f'malformed rows: row {index} must have an integer amount_cents')
        day = _clean_day(row.get('day'), index)
        row_count += 1
        total_cents += amount_cents
        if first_day is None or day < first_day:
            first_day = day
        if last_day is None or day > last_day:
            last_day = day
    return {
        'row_count': row_count,
        'total_cents': total_cents,
        'first_day': first_day,
        'last_day': last_day,
    }"}

